import {
	Component, Inject, PLATFORM_ID, ChangeDetectorRef,
	ChangeDetectionStrategy
} from '@angular/core';
import { environment } from '../../../../environments/environment';
import { isPlatformBrowser } from '@angular/common';
import { CommonModule } from '@angular/common';
import { TranslationService } from '../../../core/services/translation.service';
import { ClientsService } from '../../../providers/clients/clients.service';


@Component({
	selector: 'app-client-grid',
	standalone: true,
	imports: [CommonModule],
	templateUrl: './client-grid.component.html',
	styleUrl: './client-grid.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ClientGridComponent {
	baseUrl: any;
	clientData: any = [];
	filteredClients: any = [];
	isChangingRandom = false;
	private readonly isBrowser: boolean;
	intervalId: any;

	constructor(
		private cdr: ChangeDetectorRef,
		@Inject(PLATFORM_ID) private platformId: Object,
		public translationService: TranslationService,
		private clientsService: ClientsService
	) {
		this.isBrowser = isPlatformBrowser(platformId);
		this.baseUrl = environment.baseUrl;
		// this.baseUrl = environment.url;
	}

	ngOnInit(): void {
		this.onHover();
		this.getallClients();
	}
	getallClients() {
  this.clientsService.getClients({}).subscribe({
    next: (response: any) => {
      const clients = response.body.result;
      this.clientData = clients.map((item: any, index: number) => ({
        id: item._id || index,
        src: `${this.baseUrl}/public/logo/${item.media_image_data.src}`,
        alt: item.media_image_data.alt,
        title: item.media_image_data.name,
      }));
      this.filteredClients = this.clientData.slice(0, 15);
      this.cdr.detectChanges();
    },
    error: (err) => console.log(err)
  });
}
	onHover() {
		if (!this.isBrowser) {
			return;
		}

		if (!this.isChangingRandom) {
			this.isChangingRandom = true;
			this.intervalId = setInterval(() => {
				this.filterClients();
			}, 2000);
		}
	}

filterClients() {
	if (!this.filteredClients.length || !this.clientData.length) {
		return;
	}

	const replaceIndexes: number[] = [];

	while (
		replaceIndexes.length < Math.min(2, this.filteredClients.length)
	) {
		const idx = Math.floor(Math.random() * this.filteredClients.length);

		if (!replaceIndexes.includes(idx)) {
			replaceIndexes.push(idx);
		}
	}

	// Fade out
	replaceIndexes.forEach(i => {
		this.filteredClients[i].class = 'blur';
	});

	this.cdr.detectChanges();

	setTimeout(() => {

		replaceIndexes.forEach((i) => {

			const currentIds = this.filteredClients.map(
				(client: any) => client.id
			);

			// use clientData instead of clientImgarray
			const available = this.clientData.filter(
				(client: any) => !currentIds.includes(client.id)
			);

			const pool = available.length
				? available
				: this.clientData;

			const random =
				pool[Math.floor(Math.random() * pool.length)];

			this.filteredClients[i] = {
				...random,
				class: 'blur'
			};
		});

		this.cdr.detectChanges();

		setTimeout(() => {

			replaceIndexes.forEach(i => {
				this.filteredClients[i].class = 'show';
			});

			this.cdr.detectChanges();

			setTimeout(() => {

				this.filteredClients.forEach(
					(client: any) => client.class = ''
				);

				this.cdr.detectChanges();

			}, 600);

		}, 100);

	}, 400);
}
}
